parameters.inputSchema:
{
  "type": "array",
  "title": "Sweeply Tasks Array",
  "items": {
    "type": "object",
    "title": "Task",
    "properties": {
      "title": {
        "type": "string",
        "title": "Task Title",
        "description": "Short, action-oriented summary (e.g., 'Deliver 5 towels')."
      },
      "description": {
        "type": "string",
        "title": "Description",
        "description": "Optional longer description with context from comments."
      },
      "assigned_to": {
        "type": "object",
        "title": "Assigned Categories",
        "description": "Exactly one role containing CSV tag values.",
        "properties": {
          "Department": {
            "type": "array",
            "items": { "type": "string" }
          }
        },
        "additionalProperties": false
      },
      "priority": {
        "type": "boolean",
        "title": "Priority",
        "description": "true = high priority. false = normal/low.",
        "default": false
      },
      "due": {
        "type": "string",
        "format": "date-time",
        "title": "Due Date",
        "description": "ISO 8601 datetime for relevant tasks."
      },
      "action": {
        "type": "string",
        "enum": ["create", "update"],
        "title": "Action",
        "description": "Defines whether the task should be created or updated."
      },
      "sweeply_trace_id": {
        "type": "string",
        "title": "Sweeply Trace ID",
        "description": "Required only when action = 'update'. Optional otherwise."
      }
    },
    "required": ["title", "assigned_to", "action"]
  }
}

parameters.jsCode:
// n8n Code node (JavaScript)

/**
 * Inputs expected:
 * - Node "Extract booking details": array of booking objects (usually length 1)
 * - Node "Task agent": array with objects like { output: { tasks: [ ... ] } }
 *
 * Output:
 * - One item per enriched task:
 *   {
 *     title, description, assigned_to, priority, due,
 *     reservation_id, booking_id, booker_first_name, booker_last_name,
 *     unit_id, unit_name, unit_description, unit_group_id_from_unit,
 *     unit_group_id, unit_group_code, unit_group_name, unit_group_type
 *   }
 */

// 1) Pull inputs from other nodes
const extractedBoookingPayload = $('Start').first().json.payload;
const agentItems = $("Task agent").first().json.output;

// 2) Normalize/flatten tasks from the agent
const tasks = agentItems || [];
console.log(tasks)
if (!tasks.length) {
  return []; // no tasks to map
}

// Choose the first booking (typical flow is 1 booking -> many tasks).
// If you need multi-booking support later, add matching logic here.
const b = extractedBoookingPayload ?? {};

// 3) Build enrichment payload in snake_case
const enrichment = {
  reservation_id: b.reservationId ?? "",
  booking_id: b.bookingId ?? "",
  booker_first_name: b.bookerFirstName ?? "",
  booker_last_name: b.bookerLastName ?? "",
  primary_guest_first_name: b.primaryGuestFirstName ?? "",
  primary_guest_last_name: b.primaryGuestLastName ?? "",
  unit_id: b.unitId ?? "",
  unit_name: b.unitName ?? "",
  unit_description: b.unitDescription ?? "",
  unit_group_id_from_unit: b.unitGroupIdFromUnit ?? "",
  unit_group_id: b.unitGroupId ?? "",
  unit_group_code: b.unitGroupCode ?? "",
  unit_group_name: b.unitGroupName ?? "",
  unit_group_type: b.unitGroupType ?? "",
  property_id: b.propertyId ?? "",
  property_name: b.propertyName ?? ""
};

// 4) Emit one item per enriched task, preserving snake_case for task fields
const output = tasks.map(t => {
  // t is expected to already use snake_case keys: title, description, assigned_to, priority, due
  return {
      ...t,
      ...enrichment,
    };
});

return output;
